/**
 * Cross-links between the Datadog mock and the Fabric RTI on-call app, so either can
 * open the other on the same page, team, schedule or policy. Hosted URLs are generated by
 * `rayfin up`; update them here after a first deployment (see docs/mock-apps.md).
 */
export const APP_URLS = {
  datadog: { dev: 'http://localhost:5181', hosted: 'https://mint-shell-ff7aa7eacf-westus3.webapp.fabricapps.net' },
  rti: { dev: 'http://localhost:5184', hosted: 'https://flat-clove-167bb64dc2-westus3.webapp.fabricapps.net' },
} as const;

export type AppName = keyof typeof APP_URLS;

/** Datadog mock hash path prefix and the matching RTI app prefix. Order matters: longest first. */
const PAIRS: [datadog: string, rti: string][] = [
  ['/on-call/escalation-policies', '/escalations'],
  ['/on-call/schedules', '/schedules'],
  ['/on-call/analytics', '/analytics'],
  ['/on-call/settings', '/settings'],
  ['/on-call/teams', '/teams'],
  ['/on-call/pages', '/pages'],
  ['/monitors', '/rules'],
  ['/on-call', '/'],
];

function swap(path: string, from: 0 | 1): string {
  const clean = path.startsWith('/') ? path : `/${path}`;
  for (const pair of PAIRS) {
    const source = pair[from];
    const target = pair[from === 0 ? 1 : 0];
    if (source === '/' ? clean === '/' : clean === source || clean.startsWith(`${source}/`)) {
      return source === '/' ? target : `${target}${clean.slice(source.length)}`.replace(/^\/\//, '/');
    }
  }
  return from === 0 ? '/' : '/on-call';
}

/** `/on-call/pages/123` becomes `/pages/123`; unknown Datadog paths land on the RTI overview. */
export const toRtiPath = (datadogPath: string) => swap(datadogPath, 0);
/** `/escalations/ep-payments` becomes `/on-call/escalation-policies/ep-payments`. */
export const toDatadogPath = (rtiPath: string) => swap(rtiPath, 1);

export function counterpartUrl(app: AppName, path: string, dev: boolean): string | null {
  const base = dev ? APP_URLS[app].dev : APP_URLS[app].hosted;
  return base ? `${base}/#${path.startsWith('/') ? path : `/${path}`}` : null;
}
